<div className="facts facts-four"><span><b>{p.kcal}</b><small>{tr("kcal/100g")}</small></span><span><b>{p.protein}g</b><small>{lang==='LV'?'Olb.':'Protein'}</small></span><span><b>{p.fat}g</b><small>{lang==='LV'?'Tauki':'Fat'}</small></span><span><b>{p.carbs}g</b><small>{lang==='LV'?'Ogļh.':'Carbs'}</small></span></div>
